using DistributedMonolith.Orders.Domain;using DistributedMonolith.Orders.Infrastructure;using DistributedMonolith.SharedContracts;using Microsoft.EntityFrameworkCore;
namespace DistributedMonolith.Orders.Application;
public sealed class OrderService(OrdersDbContext db,UsersClient users,ProductsClient products){
 public async Task<(OrderResponse? Order,string? Error)>Create(CreateOrderRequest r,CancellationToken ct){if(r.Quantity<=0)return(null,"Quantity must be positive.");if(!await users.Exists(r.UserId,ct))return(null,"User does not exist.");var product=await products.Get(r.ProductId,ct);if(product is null)return(null,"Product does not exist.");var reservation=await products.Reserve(r.ProductId,r.Quantity,ct);if(!reservation.Reserved)return(null,reservation.Reason);var order=new Order{Id=Guid.NewGuid(),UserId=r.UserId,ProductId=r.ProductId,Quantity=r.Quantity,UnitPrice=product.Price,Status="Created",CreatedAt=DateTimeOffset.UtcNow};db.Add(order);await db.SaveChangesAsync(ct);return(Map(order),null);}
 public async Task<OrderResponse?>Get(Guid id){var o=await db.Orders.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id);return o is null?null:Map(o);}public async Task<OrderResponse?>Cancel(Guid id){var o=await db.Orders.FindAsync(id);if(o is null)return null;o.Status="Cancelled";await db.SaveChangesAsync();return Map(o);}static OrderResponse Map(Order o)=>new(o.Id,o.UserId,o.ProductId,o.Quantity,o.UnitPrice,o.Status,o.CreatedAt);
}
